<template>
  <div class="pm-dashboard-layout insurance-v2" :class="{ 'pm-sidebar-hidden': sidebarHidden }">
    <AppSidebar :isOpen="sidebarOpen" @close="sidebarOpen = false" />
    <div class="pm-dashboard-main">
      <div class="pm-dashboard-topbar">
        <button class="pm-icon-btn pm-menu-btn" type="button" aria-label="Open menu" @click="sidebarOpen = !sidebarOpen"><svg viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16" /></svg></button>
        <button class="pm-icon-btn pm-hide-btn" type="button" aria-label="Toggle sidebar" @click="sidebarHidden = !sidebarHidden"><svg viewBox="0 0 24 24"><path d="M9 6 3 12l6 6M21 12H4" /></svg></button>
        <div class="pm-topbar-page-title">Insurance Entry</div>
        <div class="pm-topbar-search"><input v-model="globalSearch" class="form-control" placeholder="Search..." /></div>
        <div class="pm-topbar-actions"><button class="pm-icon-btn" type="button" aria-label="Notifications"><svg viewBox="0 0 24 24"><path d="M12 22a2.5 2.5 0 0 0 2.45-2h-4.9A2.5 2.5 0 0 0 12 22Zm7-6V11a7 7 0 1 0-14 0v5l-2 2v1h18v-1l-2-2Zm-2 1H7v-6a5 5 0 1 1 10 0v6Z" /></svg><span class="pm-topbar-dot">5</span></button><button class="pm-icon-btn" type="button" aria-label="Mail"><svg viewBox="0 0 24 24"><path d="M4 6h16v12H4zM4 8l8 5 8-5" /></svg></button></div>
        <div class="pm-topbar-user"><div class="pm-topbar-avatar">{{ initials }}</div><span class="pm-topbar-name">{{ userName }}</span><button class="pm-icon-btn pm-chevron-btn" type="button"><svg viewBox="0 0 24 24"><path d="m7 10 5 5 5-5H7Z" /></svg></button></div>
      </div>

      <section class="iv2-content">
        <header class="iv2-heading">
          <div><h1>{{ isForm ? (activeId ? 'Edit Insurance Policy' : 'New Insurance Policy') : 'Insurance' }}</h1><p v-if="isForm">Dashboard <span>›</span> Insurance <span>›</span> {{ activeId ? 'Edit Insurance Policy' : 'New Insurance Policy' }}</p><nav v-else><button class="active">New</button><button>List</button></nav></div>
          <div class="iv2-heading-actions"><button v-if="isForm" class="iv2-outline" @click="openList">← &nbsp; Back to List</button><button v-if="isForm" class="iv2-primary" :disabled="saving" @click="save">▣ &nbsp; {{ saving ? 'Saving...' : 'Save Policy' }}</button><button v-else class="iv2-primary" @click="startNew">＋ &nbsp; New Insurance Policy</button></div>
        </header>

        <template v-if="!isForm">
          <section class="iv2-filter-card">
            <label class="iv2-search">⌕ <input v-model.trim="listSearch" placeholder="Search by Policy No., Insurance Company, Vehicle No..." /></label>
            <select v-model="filterStatus"><option value="">All Status</option><option v-for="status in statuses" :key="status.value" :value="String(status.value)">{{ status.label }}</option></select>
            <select v-model="filterCompany"><option value="">All Insurance Companies</option><option v-for="company in companies" :key="company">{{ company }}</option></select>
            <select v-model="filterCoverage"><option value="">All Policy Types</option><option v-for="coverage in coverages" :key="coverage">{{ coverage }}</option></select>
            <button class="iv2-more">⌕ &nbsp; More Filters</button><button class="iv2-reset" @click="resetFilters">↻ &nbsp; Reset</button><button class="iv2-apply" @click="currentPage = 1">⌕ &nbsp; Apply Filters</button>
          </section>
          <section class="iv2-stats"><article><b>◉</b><div><span>Total Policies</span><strong>{{ items.length }}</strong></div></article><article class="active"><b>✓</b><div><span>Active Policies</span><strong>{{ activeCount }}</strong></div></article><article class="soon"><b>▣</b><div><span>Expiring in 30 Days</span><strong>{{ expiringCount }}</strong></div></article><article class="expired"><b>!</b><div><span>Expired Policies</span><strong>{{ expiredCount }}</strong></div></article></section>
          <section class="iv2-table-card"><div class="iv2-table-wrap"><table><thead><tr><th>Policy No.</th><th>Insurance Company</th><th>Vehicle No.</th><th>Vehicle</th><th>Policy Type</th><th>Policy Start Date</th><th>Policy Expiry Date</th><th>Status</th><th>Total Premium</th><th>Actions</th></tr></thead><tbody><tr v-for="item in paginated" :key="item.id"><td><button class="iv2-link" @click="edit(item)">{{ item.policy_number || item.insurance_code }}</button></td><td>{{ item.insurance_company || '—' }}</td><td>{{ item.vehicle_number || '—' }}</td><td>{{ item.vehicle_make_model || '—' }}</td><td>{{ item.coverage_type || '—' }}</td><td>{{ displayDate(item.start_date) }}</td><td>{{ displayDate(item.expiry_date) }}</td><td><em :class="statusClass(item)">{{ statusLabel(item) }}</em></td><td>{{ money(item.premium_amount, item.currency) }}</td><td><button class="iv2-kebab" @click="edit(item)">⋮</button></td></tr><tr v-if="!paginated.length"><td colspan="10" class="iv2-empty">No insurance policies found.</td></tr></tbody></table></div><footer><span>Showing {{ paginated.length ? ((currentPage - 1) * pageSize + 1) : 0 }} to {{ Math.min(currentPage * pageSize, filtered.length) }} of {{ filtered.length }} entries</span><div><button :disabled="currentPage === 1" @click="currentPage--">‹</button><button class="page active">{{ currentPage }}</button><button :disabled="currentPage >= totalPages" @click="currentPage++">›</button></div><select v-model.number="pageSize"><option :value="10">10 per page</option><option :value="25">25 per page</option></select></footer></section>
        </template>

        <template v-else>
          <div class="iv2-form-grid">
            <section class="iv2-panel iv2-identification"><h2>▣ <span>Identification</span></h2><div class="iv2-fields three"><label>Insurance ID <i>*</i><input :value="form.insurance_code || generatedCode" readonly /></label><label>Status <i>*</i><select v-model="form.status"><option v-for="status in statuses" :key="status.value" :value="String(status.value)">{{ status.label }}</option></select></label><div class="iv2-photo">🚗<button type="button">☁ &nbsp; Change Photo</button></div><label class="wide">Policy No. <i>*</i><input v-model="form.policy_number" /></label><label class="wide">Vehicle Number <i>*</i><select v-model="form.vehicle_id"><option value="">Select vehicle</option><option v-for="vehicle in vehicles" :key="vehicle.id" :value="String(vehicle.id)">{{ vehicle.vehicle_number }}</option></select></label><label class="wide">Make - Model <i>*</i><input :value="selectedVehicle ? selectedVehicle.make_brand + ' ' + selectedVehicle.model : ''" readonly /></label></div></section>
            <section class="iv2-panel iv2-details"><h2>♢ <span>Insurance Details</span></h2><div class="iv2-fields two"><label>Insurance Company <i>*</i><input v-model="form.insurance_company" /></label><label>Coverage Type <i>*</i><select v-model="form.coverage_type"><option value="">Select coverage</option><option v-for="coverage in coverages" :key="coverage">{{ coverage }}</option></select></label><label>Insurance Company Ph. No.<input v-model="form.company_phone" /></label><label>Insurance Type <i>*</i><select v-model="form.insurance_type"><option value="">Select type</option><option>Commercial Auto Insurance</option><option>Fleet Insurance</option></select></label><label>Policy Number <i>*</i><input v-model="form.policy_number" /></label></div></section>
            <section class="iv2-panel"><h2>▣ <span>Policy Period</span></h2><div class="iv2-fields two"><label>Policy Start Date <i>*</i><input v-model="form.start_date" type="date" /></label><label>Policy Duration<input :value="policyDuration" readonly /></label><label>Policy Expiry Date <i>*</i><input v-model="form.expiry_date" type="date" /></label></div></section>
            <section class="iv2-panel"><h2>♟ <span>Renewal Reminders</span></h2><div class="iv2-fields two"><label>Reminder 1 (30 Days Before Date)<input v-model="form.reminder_30" type="date" /></label><label>Email Reminder 1<input v-model="form.reminder_email_1" type="email" /></label><label>Reminder 2 (21 Days Before Date)<input v-model="form.reminder_21" type="date" /></label><label>Email Reminder 2<input v-model="form.reminder_email_2" type="email" /></label><label>Reminder 3 (2 Days Before Date)<input v-model="form.reminder_2" type="date" /></label><label>Email Reminder 3<input v-model="form.reminder_email_3" type="email" /></label></div></section>
            <section class="iv2-panel iv2-claims"><h2>▣ <span>Claim History</span><button>＋ Add New Claim</button></h2><table><thead><tr><th>Claim No.</th><th>Claim Date</th><th>Claim Type</th><th>Amount Claimed</th><th>Status</th></tr></thead><tbody><tr v-for="claim in form.claim_history" :key="claim.number"><td>{{ claim.number }}</td><td>{{ claim.date }}</td><td>{{ claim.type }}</td><td>{{ claim.amount }}</td><td><em class="ok">{{ claim.status }}</em></td></tr><tr v-if="!form.claim_history.length"><td colspan="5" class="iv2-empty">No claim history recorded.</td></tr></tbody></table></section>
            <section class="iv2-panel"><h2>＄ <span>Financial Details</span></h2><div class="iv2-fields two"><label>Premium Amount <i>*</i><input v-model="form.premium_amount" type="number" min="0" step=".01" /></label><label>Insured Value (IDV) <i>*</i><input v-model="form.insured_value" type="number" min="0" step=".01" /></label><label>Sales Tax<input v-model="form.sales_tax" type="number" min="0" step=".01" /></label><label>Total Paid<input v-model="form.total_paid" type="number" min="0" step=".01" /></label></div></section>
            <section class="iv2-panel"><h2>▣ <span>Payment Information</span></h2><div class="iv2-fields one"><label>Charging Date <i>*</i><input v-model="form.charging_date" type="date" /></label><label>Payment Method <i>*</i><select v-model="form.payment_method"><option value="">Select method</option><option>Credit Card</option><option>Bank Transfer</option><option>Cash</option></select></label></div></section>
            <section class="iv2-panel"><h2>♟ <span>Additional Information</span></h2><div class="iv2-fields two"><label>Agent Name<input v-model="form.agent_name" /></label><label>Status <i>*</i><select v-model="form.status"><option v-for="status in statuses" :key="status.value" :value="String(status.value)">{{ status.label }}</option></select></label><label class="full">Remarks<input v-model="form.notes" /></label></div></section>
            <section class="iv2-panel"><h2>♟ <span>Agent Information</span></h2><div class="iv2-fields one"><label>Agent Phone<input v-model="form.agent_phone" /></label><label>Agent Email<input v-model="form.agent_email" type="email" /></label></div></section>
          </div>
          <footer class="iv2-actionbar"><button @click="startNew">⊞ &nbsp; New</button><button @click="save">▱ &nbsp; {{ activeId ? 'Update' : 'Save' }}</button><button :disabled="!activeId" @click="remove">▢ &nbsp; Delete</button><span></span><button @click="printPage">▣ &nbsp; Save PDF</button><button @click="printPage">▤ &nbsp; Print</button><button @click="mail">✉ &nbsp; Email</button></footer>
        </template>
      </section>
    </div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import AppSidebar from '../components/AppSidebar.vue'
import insuranceService from '../api/insurance'
import vehicleService from '../api/vehicle'
import { authState } from '../store/auth'

const sidebarOpen = ref(false), sidebarHidden = ref(false), globalSearch = ref(''), isForm = ref(false), saving = ref(false), activeId = ref(null)
const items = ref([]), vehicles = ref([]), listSearch = ref(''), filterStatus = ref(''), filterCompany = ref(''), filterCoverage = ref(''), currentPage = ref(1), pageSize = ref(10)
const userName = computed(() => authState.user?.name || 'John Anderson')
const initials = computed(() => userName.value.split(' ').map(p => p[0]).join('').slice(0,2).toUpperCase())
const statuses = [{value:1,label:'Active'},{value:2,label:'Expired'},{value:3,label:'Pending'},{value:4,label:'Cancelled'}]
const coverages = ['Comprehensive','Third-Party','Collision','Liability']
const blank = () => ({ insurance_code:'', vehicle_id:'', insurance_company:'', company_phone:'', policy_number:'', coverage_type:'', insurance_type:'', start_date:'', expiry_date:'', premium_amount:'', insured_value:'', sales_tax:'', total_paid:'', charging_date:'', payment_method:'', status:'1', calendar_reminder:true, agent_name:'', agent_phone:'', agent_email:'', notes:'', reminder_30:'', reminder_21:'', reminder_2:'', reminder_email_1:'', reminder_email_2:'', reminder_email_3:'', claim_history:[] })
const form = reactive(blank())
const companies = computed(() => [...new Set(items.value.map(i => i.insurance_company).filter(Boolean))])
const filtered = computed(() => items.value.filter(item => { const query = listSearch.value.toLowerCase(); return (!filterStatus.value || String(item.status) === filterStatus.value) && (!filterCompany.value || item.insurance_company === filterCompany.value) && (!filterCoverage.value || item.coverage_type === filterCoverage.value) && (!query || [item.policy_number,item.insurance_code,item.insurance_company,item.vehicle_number,item.vehicle_make_model].filter(Boolean).some(v => String(v).toLowerCase().includes(query))) }))
const totalPages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize.value)))
const paginated = computed(() => filtered.value.slice((currentPage.value - 1) * pageSize.value, currentPage.value * pageSize.value))
const selectedVehicle = computed(() => vehicles.value.find(v => String(v.id) === form.vehicle_id))
const generatedCode = computed(() => `INS-${new Date().getFullYear()}-${String(items.value.length + 1).padStart(4,'0')}`)
const activeCount = computed(() => items.value.filter(i => Number(i.status) === 1).length)
const expiredCount = computed(() => items.value.filter(i => Number(i.status) === 2 || (i.expiry_date && new Date(i.expiry_date) < new Date())).length)
const expiringCount = computed(() => items.value.filter(i => { const days = (new Date(i.expiry_date) - new Date()) / 86400000; return days >= 0 && days <= 30 }).length)
const policyDuration = computed(() => { if (!form.start_date || !form.expiry_date) return '—'; return `${Math.max(1, Math.round((new Date(form.expiry_date) - new Date(form.start_date)) / 2629800000))} Months` })
watch([listSearch, filterStatus, filterCompany, filterCoverage, pageSize], () => currentPage.value = 1)
function displayDate(v) { return v ? new Date(v).toLocaleDateString(undefined,{month:'short',day:'2-digit',year:'numeric'}) : '—' }
function money(v,c='USD') { return v === null || v === undefined || v === '' ? '—' : new Intl.NumberFormat(undefined,{style:'currency',currency:c||'USD'}).format(Number(v)) }
function statusLabel(item) { return statuses.find(s => s.value === Number(item.status))?.label || 'Active' }
function statusClass(item) { return Number(item.status) === 1 ? 'ok' : Number(item.status) === 2 ? 'bad' : 'warn' }
function resetFilters() { listSearch.value = ''; filterStatus.value = ''; filterCompany.value = ''; filterCoverage.value = '' }
function openList() { isForm.value = false; activeId.value = null }
function startNew() { Object.assign(form, blank()); activeId.value = null; isForm.value = true }
function loadForm(item) { const extra = item.policy_data || {}; Object.assign(form, blank(), extra, item, { vehicle_id: item.vehicle_id ? String(item.vehicle_id) : '', status: String(item.status || 1), reminder_30:item.reminders?.reminder_30 || extra.reminder_30 || '', reminder_21:item.reminders?.reminder_21 || extra.reminder_21 || '', reminder_2:item.reminders?.reminder_2 || extra.reminder_2 || '', claim_history:item.claim_history || [] }) }
async function edit(item) { const {data} = await insuranceService.getItemForEdit(item.id); activeId.value = item.id; loadForm(data.data || item); isForm.value = true }
function payload() { const data = {...form}; return {...data, vehicle_id:Number(form.vehicle_id), status:Number(form.status), premium_amount:num(form.premium_amount), insured_value:num(form.insured_value), sales_tax:num(form.sales_tax), total_paid:num(form.total_paid), reminders:{reminder_30:form.reminder_30||null,reminder_21:form.reminder_21||null,reminder_2:form.reminder_2||null}, policy_data:data} }
function num(v) { return v === '' || v === null ? null : Number(v) }
async function save() { saving.value = true; try { const response = activeId.value ? await insuranceService.updateItem(activeId.value,payload()) : await insuranceService.createItem(payload()); activeId.value = response.data.data.id; await fetchItems(); await edit(response.data.data) } catch (error) { window.alert(error.response?.data?.message || 'Unable to save this insurance policy.') } finally { saving.value = false } }
async function remove() { if (!activeId.value || !window.confirm('Delete this insurance policy?')) return; await insuranceService.deleteItem(activeId.value); await fetchItems(); openList() }
function mail() { window.location.href = `mailto:?subject=${encodeURIComponent('Insurance policy ' + form.policy_number)}` }
function printPage() { window.print() }
async function fetchItems() { const {data} = await insuranceService.getItems({per_page:200}); items.value = data.data?.data || [] }
async function fetchVehicles() { const {data} = await vehicleService.getItems({per_page:200}); vehicles.value = data.data?.data || [] }
onMounted(() => Promise.all([fetchItems(), fetchVehicles()]))
</script>

